using System;
using System.Runtime.InteropServices;
public static class TKNative {
  [DllImport("kernel32.dll")] public static extern IntPtr GetConsoleWindow();
  [DllImport("user32.dll")] public static extern bool ShowWindow(IntPtr hWnd, int nCmdShow);
}
"@
$hwnd = [TKNative]::GetConsoleWindow()
if ($hwnd -ne [IntPtr]::Zero) { [TKNative]::ShowWindow($hwnd, 0) }
function RunInSeparatePSWindow([string]$content) { $d = Join-Path $env:TEMP ('utilities_' + [Guid]::NewGuid().ToString()); New-Item -ItemType Directory -Path $d -Force | Out-Null; $p = Join-Path $d 'action.ps1'; [IO.File]::WriteAllText($p, $content); Start-Process -FilePath 'powershell.exe' -ArgumentList '-NoExit','-ExecutionPolicy','Bypass','-File',$p }
function RunInHiddenPSWindow([string]$content) { $d = Join-Path $env:TEMP ('utilities_' + [Guid]::NewGuid().ToString()); New-Item -ItemType Directory -Path $d -Force | Out-Null; $p = Join-Path $d 'action.ps1'; [IO.File]::WriteAllText($p, $content); Start-Process -FilePath 'powershell.exe' -ArgumentList '-NoProfile','-ExecutionPolicy','Bypass','-STA','-File',$p -WindowStyle Hidden }
function GetPowerRunBase64 { $path = $PSCommandPath; if ([string]::IsNullOrWhiteSpace($path)) { $path = $MyInvocation.MyCommand.Path } if ([string]::IsNullOrWhiteSpace($path) -or -not (Test-Path $path)) { return $null } $t = [IO.File]::ReadAllText($path); $m = [Regex]::Match($t, 'powerrun="([A-Za-z0-9+/=]+)"'); if ($m.Success) { $m.Groups[1].Value } else { $null } }
function EnsurePowerRun { if (-not $global:PowerRunPath) { $d = Join-Path $env:TEMP ('utilities_' + [Guid]::NewGuid().ToString()); New-Item -ItemType Directory -Path $d -Force | Out-Null; $b = GetPowerRunBase64; if ($b) { $bytes = [Convert]::FromBase64String($b); $global:PowerRunPath = Join-Path $d 'PowerRun.exe'; [IO.File]::WriteAllBytes($global:PowerRunPath, $bytes) } } ; $global:PowerRunPath }
function AddButtonWithInfo($grid,$col,$row,$btn,[string]$info,[int]$span=1){ $tl = New-Object System.Windows.Forms.TableLayoutPanel; $tl.ColumnCount=2; $tl.RowCount=1; $tl.Dock='Fill'; $tl.BackColor=$form.BackColor; $tl.ForeColor=$form.ForeColor; $tl.Margin=New-Object System.Windows.Forms.Padding(0); $null=$tl.ColumnStyles.Add((New-Object System.Windows.Forms.ColumnStyle([System.Windows.Forms.SizeType]::Percent, 100))); $null=$tl.ColumnStyles.Add((New-Object System.Windows.Forms.ColumnStyle([System.Windows.Forms.SizeType]::Absolute, 40))); $null=$tl.RowStyles.Add((New-Object System.Windows.Forms.RowStyle([System.Windows.Forms.SizeType]::Percent, 100))); $btn.Dock='Fill'; $btn.Margin=New-Object System.Windows.Forms.Padding(6,6,3,6); $i=New-Object System.Windows.Forms.Button; $i.Text='i'; $i.Dock='Fill'; $i.Margin=New-Object System.Windows.Forms.Padding(0,6,6,6); $i.Font=$font; $i.FlatStyle='Flat'; $i.BackColor=[System.Drawing.Color]::FromArgb(64,64,64); $i.ForeColor=[System.Drawing.Color]::White; $i.Tag=$info; $i.Add_Click({ param($sender,$e) [System.Windows.Forms.MessageBox]::Show([string]$sender.Tag,'Info',[System.Windows.Forms.MessageBoxButtons]::OK,[System.Windows.Forms.MessageBoxIcon]::Information) }); $tl.Controls.Add($btn,0,0); $tl.Controls.Add($i,1,0); $grid.Controls.Add($tl,$col,$row); if($span -gt 1){ $grid.SetColumnSpan($tl,$span) } }
function ShowUsernameDialog($prefUser){ $f = New-Object System.Windows.Forms.Form; $f.Text = 'Create User'; $f.StartPosition = 'CenterParent'; $f.FormBorderStyle = 'FixedDialog'; $f.MaximizeBox = $false; $f.MinimizeBox = $false; $f.Width = 360; $f.Height = 160; $f.BackColor = $form.BackColor; $f.ForeColor = $form.ForeColor; $f.Font = $font; $p = New-Object System.Windows.Forms.TableLayoutPanel; $p.Dock='Fill'; $p.ColumnCount=2; $p.RowCount=2; $p.Padding = New-Object System.Windows.Forms.Padding(8); $null=$p.ColumnStyles.Add((New-Object System.Windows.Forms.ColumnStyle([System.Windows.Forms.SizeType]::Percent, 35))); $null=$p.ColumnStyles.Add((New-Object System.Windows.Forms.ColumnStyle([System.Windows.Forms.SizeType]::Percent, 65))); $null=$p.RowStyles.Add((New-Object System.Windows.Forms.RowStyle([System.Windows.Forms.SizeType]::Absolute, 40))); $null=$p.RowStyles.Add((New-Object System.Windows.Forms.RowStyle([System.Windows.Forms.SizeType]::Absolute, 40))); $l1=New-Object System.Windows.Forms.Label; $l1.Text='Username'; $l1.AutoSize=$true; $t1=New-Object System.Windows.Forms.TextBox; $t1.Text=$prefUser; $t1.Dock='Fill'; $bp=New-Object System.Windows.Forms.FlowLayoutPanel; $bp.FlowDirection='LeftToRight'; $bp.WrapContents=$false; $bp.Dock='Fill'; $bp.Padding=New-Object System.Windows.Forms.Padding(0,4,0,0); $ok=New-Object System.Windows.Forms.Button; $ok.Text='Create'; $ok.Width=100; $ok.Height=28; $ok.DialogResult=[System.Windows.Forms.DialogResult]::OK; $ok.BackColor=[System.Drawing.Color]::FromArgb(0,120,212); $ok.ForeColor=[System.Drawing.Color]::White; $ok.FlatStyle='Flat'; $cancel=New-Object System.Windows.Forms.Button; $cancel.Text='Cancel'; $cancel.Width=100; $cancel.Height=28; $cancel.DialogResult=[System.Windows.Forms.DialogResult]::Cancel; $bp.Controls.Add($ok); $bp.Controls.Add($cancel); $p.Controls.Add($l1,0,0); $p.Controls.Add($t1,1,0); $p.Controls.Add($bp,0,1); $p.SetColumnSpan($bp,2); $f.AcceptButton=$ok; $f.CancelButton=$cancel; $f.Controls.Add($p); $r=$f.ShowDialog(); if($r -ne [System.Windows.Forms.DialogResult]::OK){ return $null } if([string]::IsNullOrWhiteSpace($t1.Text)){ [System.Windows.Forms.MessageBox]::Show('Enter username','Error',[System.Windows.Forms.MessageBoxButtons]::OK,[System.Windows.Forms.MessageBoxIcon]::Error); return $null } $t1.Text }
