# Button: Install ADB/Fastboot
# Purpose: Install Android platform-tools (ADB/Fastboot) on this machine.
# What it does:
# - Downloads the latest platform-tools ZIP from Google to 'C:\Program Files'.
# - Extracts the ZIP into 'C:\Program Files\\platform-tools'.
# - Appends the directory to the system PATH using 'setx'.
# Requirements: Administrator privileges and internet access.
# Feedback: Opens a separate PowerShell window that prints progress and errors, then stays open.
$btnAdb = New-Object System.Windows.Forms.Button
$btnAdb.Dock = 'Fill'
$btnAdb.Margin = New-Object System.Windows.Forms.Padding(6)
$btnAdb.Text = "Install ADB/Fastboot"
$btnAdb.Font = $font
$btnAdb.FlatStyle = 'Flat'
$btnAdb.UseVisualStyleBackColor = $false
$btnAdb.BackColor = [System.Drawing.Color]::FromArgb(0,120,212)
$btnAdb.ForeColor = [System.Drawing.Color]::White
$btnAdb.Add_Click({
    $content = @'
 # begin error-handled block
 try {
 # suppress progress output for cleaner logs
     $ProgressPreference = 'SilentlyContinue'
 # download platform-tools ZIP
     Invoke-WebRequest "https://dl.google.com/android/repository/platform-tools-latest-windows.zip" -OutFile "C:\Program Files\platform-tools.zip" | Out-Null
 # extract ZIP to Program Files
     Expand-Archive -Path "C:\Program Files\platform-tools.zip" -DestinationPath "C:\Program Files" -Force | Out-Null
 # delete ZIP after extraction
     Remove-Item -Path "C:\Program Files\platform-tools.zip" -Force
 # append platform-tools to PATH
     & cmd.exe /c setx PATH "$env:PATH;C:\Program Files\platform-tools"
 # success message
     Write-Host "ADB and Fastboot installed"
 # handle any exception
 } catch {
 # failure message
     Write-Host "ADB/Fastboot installation failed"
 }
'@
    RunInSeparatePSWindow $content
})
AddButtonWithInfo $grid 1 4 $btnAdb "Downloads latest Android platform-tools to C:\Program Files`nExtracts to C:\Program Files\platform-tools and updates PATH via setx`nRequires admin and internet; runs in separate PowerShell window"
# Button: Install Microsoft Store
# Purpose: Repair or reinstall Microsoft Store components.
# What it does:
# - Runs 'WSReset.exe -i' twice with a delay; this resets Store cache and repairs install.
# Notes: The operation may take several minutes and shows limited console output.
# Feedback: Runs in a separate PowerShell window and remains open for inspection.
$btnStore = New-Object System.Windows.Forms.Button
$btnStore.Dock = 'Fill'
$btnStore.Margin = New-Object System.Windows.Forms.Padding(6)
$btnStore.Text = "Install Microsoft Store"
$btnStore.Font = $font
$btnStore.FlatStyle = 'Flat'
$btnStore.UseVisualStyleBackColor = $false
$btnStore.BackColor = [System.Drawing.Color]::FromArgb(0,120,212)
$btnStore.ForeColor = [System.Drawing.Color]::White
$btnStore.Add_Click({
    $content = @'
 # begin error-handled block
 try {
 # suppress progress output
     $ProgressPreference = 'SilentlyContinue'
 # log start
     Write-Host "Starting Microsoft Store repair/reset..."
 # user notice
     Write-Host "Note: It may take up to 5 minutes before Store appears."
 # reset Microsoft Store cache
     & WSReset.exe -i
 # wait to allow operation to progress
     Start-Sleep -Seconds 20
 # run reset a second time
     & WSReset.exe -i
 # short delay
     Start-Sleep -Seconds 4
 # final message
     Write-Host "Repair started. Store may take up to 5 minutes to appear"
 # handle any exception
 } catch {
 # failure message
     Write-Host "Microsoft Store repair failed"
 }
'@
    RunInSeparatePSWindow $content
})
AddButtonWithInfo $grid 0 1 $btnStore "Runs WSReset.exe -i twice with delays to reset Store cache`nRepairs Microsoft Store installation; may take several minutes`nShows progress in a separate PowerShell window"
# Button: Remove Microsoft Edge
# Purpose: Uninstall Microsoft Edge without winget, using registry uninstall and UWP stub.
# What it does:
# - Reads 'UninstallString' from HKLM\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\Microsoft Edge.
# - Enables uninstall via 'EdgeUpdateDev\\AllowUninstall' and clears experiment labels.
# - Creates a temporary 'dllhost.exe' proxy and a UWP stub exe to bypass uninstall checks.
# - Executes the uninstall with '--force-uninstall' and cleans up artifacts.
# Requirements: Administrator privileges. Close Edge before running if possible.
# Feedback: Prints status and errors in a separate PowerShell window and keeps it open.
$btnEdgeRemove = New-Object System.Windows.Forms.Button
$btnEdgeRemove.Dock = 'Fill'
$btnEdgeRemove.Margin = New-Object System.Windows.Forms.Padding(6)
$btnEdgeRemove.Text = "Remove Edge"
$btnEdgeRemove.Font = $font
$btnEdgeRemove.FlatStyle = 'Flat'
$btnEdgeRemove.UseVisualStyleBackColor = $false
$btnEdgeRemove.BackColor = [System.Drawing.Color]::FromArgb(0,120,212)
$btnEdgeRemove.ForeColor = [System.Drawing.Color]::White
$btnEdgeRemove.Add_Click({
    $content = @'
# Thanks to ave9858
 # begin error-handled block
 try {
 # stop on errors to catch in try/catch
     $ErrorActionPreference = "Stop"
 # use 32-bit registry view
     $regView = [Microsoft.Win32.RegistryView]::Registry32
 # open HKLM\SOFTWARE\Microsoft writable
     $microsoft = [Microsoft.Win32.RegistryKey]::OpenBaseKey([Microsoft.Win32.RegistryHive]::LocalMachine, $regView).OpenSubKey('SOFTWARE\Microsoft', $true)
 # UWP Edge stub path
     $edgeUWP = "$env:SystemRoot\SystemApps\Microsoft.MicrosoftEdge_8wekyb3d8bbwe"
 # Edge uninstall key
     $uninstallRegKey = $microsoft.OpenSubKey('Windows\CurrentVersion\Uninstall\Microsoft Edge')
 # abort if missing
     if ($null -eq $uninstallRegKey) { Write-Error "Edge is not installed!" }
 # add force flag
     $uninstallString = $uninstallRegKey.GetValue('UninstallString') + ' --force-uninstall'
 # choose system temp
     $tempPath = "$env:SystemRoot\SystemTemp"
 # fallback temp dir
     if (-not (Test-Path -Path $tempPath) ) { $tempPath = New-Item "$env:SystemRoot\Temp\$([Guid]::NewGuid().Guid)" -ItemType Directory }
 # path to fake process host
     $fakeDllhostPath = "$tempPath\dllhost.exe"
 # Edge client state key
     $edgeClient = $microsoft.OpenSubKey('EdgeUpdate\ClientState\{56EB18F8-B008-4CBD-B6D2-8C97FE7E9062}', $true)
 # clear experiment labels
     if ($null -ne $edgeClient.GetValue('experiment_control_labels')) { $edgeClient.DeleteValue('experiment_control_labels') }
 # allow uninstall via dev key
     $microsoft.CreateSubKey('EdgeUpdateDev').SetValue('AllowUninstall', '')
 # create fake dllhost executable
     Copy-Item "$env:SystemRoot\System32\cmd.exe" -Destination $fakeDllhostPath
 # ensure UWP folder exists
     [void](New-Item $edgeUWP -ItemType Directory -ErrorVariable fail -ErrorAction SilentlyContinue)
 # create stub exe
     [void](New-Item "$edgeUWP\MicrosoftEdge.exe" -ErrorAction Continue)
 # run uninstall via stub
     Start-Process $fakeDllhostPath "/c $uninstallString" -WindowStyle Hidden -Wait
 # cleanup stub exe
     [void](Remove-Item "$edgeUWP\MicrosoftEdge.exe" -ErrorAction Continue)
 # remove fake dllhost
     [void](Remove-Item $fakeDllhostPath -ErrorAction Continue)
 # remove UWP folder if created here
     if (-not $fail) { [void](Remove-Item "$edgeUWP") }
 # success message
     Write-Output "Microsoft Edge removed"
 # handle any exception
 } catch {
 # failure message
     Write-Output "Microsoft Edge removal failed"
 }
'@
    RunInSeparatePSWindow $content
})
AddButtonWithInfo $grid 0 0 $btnEdgeRemove "Reads UninstallString under HKLM\\...\\Uninstall\\Microsoft Edge`nEnables Edge uninstall (EdgeUpdateDev AllowUninstall) and clears experiment labels`nCreates temp dllhost.exe and UWP stub, runs --force-uninstall, cleans up`nRequires admin; close Edge before running"
$labelUser = New-Object System.Windows.Forms.Label
 
# Button: Create local admin user
# Purpose: Create a new local user and grant Administrator role.
# What it does:
# - Prompts for username via GUI textbox and runs 'net.exe user /add'.
# - Adds the user to the local 'Administrators' group.
# Notes: No password is set here; configure a password afterward.
# Feedback: Prints results in the separate PowerShell window and remains open.
$btnAddUser = New-Object System.Windows.Forms.Button
$btnAddUser.Dock = 'Fill'
$btnAddUser.Margin = New-Object System.Windows.Forms.Padding(6)
$btnAddUser.Text = "Create admin user"
$btnAddUser.Font = $font
$btnAddUser.FlatStyle = 'Flat'
$btnAddUser.UseVisualStyleBackColor = $false
$btnAddUser.BackColor = [System.Drawing.Color]::FromArgb(0,120,212)
$btnAddUser.ForeColor = [System.Drawing.Color]::White
$btnAddUser.Add_Click({
    $name = ShowUsernameDialog ''
    if (-not $name) { return }
    $pr = EnsurePowerRun
    $content = @'
 # begin error-handled block
 try {
 # resolved path to PowerRun helper
   $pr = "__PR__"
 # username from dialog
   $usr = "__USR__"
 # create local user (elevated if PowerRun)
   if (Test-Path $pr) { & $pr cmd.exe /c "net user `"$usr`" /add" } else { & net.exe user "$usr" /add }
 # add user to Administrators group
   if (Test-Path $pr) { & $pr cmd.exe /c "net localgroup administrators `"$usr`" /add" } else { & net.exe localgroup administrators "$usr" /add }
 # success message
   Write-Host "Admin user created"
 # handle any exception
 } catch {
 # failure message with error
   Write-Host ("User creation failed: " + $_.Exception.Message)
 }
'@
    $content = $content.Replace('__PR__', $pr).Replace('__USR__', $name)
    RunInSeparatePSWindow $content
})
AddButtonWithInfo $grid 0 3 $btnAddUser "Prompts for username, then creates an admin user`nRuns elevated if PowerRun is available`nShows progress in a separate PowerShell window"
# Button: Reinstall Microsoft Edge
# Purpose: Install Microsoft Edge via winget.
# What it does:
# - Ensures winget dependencies (App Installer, VCLibs, WinUI) if missing.
# - Runs 'winget install Microsoft.Edge' silently.
# Requirements: Administrator privileges and internet access.
# Feedback: Shows progress/errors inline; leaves window open.
$btnEdgeInstall = New-Object System.Windows.Forms.Button
$btnEdgeInstall.Dock = 'Fill'
$btnEdgeInstall.Margin = New-Object System.Windows.Forms.Padding(6)
$btnEdgeInstall.Text = "Reinstall Edge"
$btnEdgeInstall.Font = $font
$btnEdgeInstall.FlatStyle = 'Flat'
$btnEdgeInstall.UseVisualStyleBackColor = $false
$btnEdgeInstall.BackColor = [System.Drawing.Color]::FromArgb(0,120,212)
$btnEdgeInstall.ForeColor = [System.Drawing.Color]::White
$btnEdgeInstall.Add_Click({
    try {
        $content = @'
 # begin error-handled block
 try {
 # installs App Installer + deps if winget missing
     function InstallWinGet2 {
 # suppress progress output
         $ProgressPreference = 'SilentlyContinue'
 # simple web client for downloads
         $wc = New-Object Net.WebClient
 # max retry attempts
         $max = 3
 # retry wrapper
         function DownloadWithRetries2($u,$p){$a=0;while($a -lt $max){try{$wc.DownloadFile($u,$p);return $true}catch{$a++;Start-Sleep -Seconds 2}};return $false}
 # App Installer bundle URL
         $u1 = 'https://aka.ms/getwinget'
 # local filename
         $p1 = "Microsoft.DesktopAppInstaller_8wekyb3d8bbwe.msixbundle"
 # abort if failed
         if (-not (DownloadWithRetries2 $u1 $p1)) { return }
 # VCLibs URL
         $u2 = 'https://aka.ms/Microsoft.VCLibs.x64.14.00.Desktop.appx'
 # local filename
         $p2 = "Microsoft.VCLibs.x64.14.00.Desktop.appx"
 # abort if failed
         if (-not (DownloadWithRetries2 $u2 $p2)) { return }
 # WinUI URL
         $u3 = 'https://github.com/microsoft/microsoft-ui-xaml/releases/download/v2.8.6/Microsoft.UI.Xaml.2.8.x64.appx'
 # local filename
         $p3 = "Microsoft.UI.Xaml.2.8.x64.appx"
 # abort if failed
         if (-not (DownloadWithRetries2 $u3 $p3)) { return }
 # install VCLibs
         Add-AppxPackage $p2
 # install WinUI
         Add-AppxPackage $p3
 # install App Installer
         Add-AppxPackage $p1
     }
 # ensure winget present
     if (-not (Test-Path "$env:LOCALAPPDATA\Microsoft\WindowsApps\winget.exe")) { InstallWinGet2 }
 # install Edge silently
     & "$env:LOCALAPPDATA\Microsoft\WindowsApps\winget.exe" install Microsoft.Edge --accept-source-agreements --silent
 # success message
     Write-Host "Microsoft Edge installed"
 # handle any exception
 } catch {
 # failure message
     Write-Host "Microsoft Edge installation failed"
 }
'@
        RunInSeparatePSWindow $content
    } catch {
        [System.Windows.Forms.MessageBox]::Show("Edge reinstallation error","Error",[System.Windows.Forms.MessageBoxButtons]::OK,[System.Windows.Forms.MessageBoxIcon]::Error)
    }
})
AddButtonWithInfo $grid 1 0 $btnEdgeInstall "Ensures winget by installing App Installer, VCLibs, and WinUI if missing`nInstalls Microsoft Edge via winget --silent`nRequires admin and internet; runs in a separate window"
# Button: Clean Windows Update cache
# Purpose: Fix common Windows Update issues by clearing cache.
# What it does:
# - Stops the 'wuauserv' service.
# - Deletes 'C:\Windows\\SoftwareDistribution\\Download' and recreates the folder.
# - Restarts 'wuauserv'.
# Feedback: Prints each step in the separate window and remains open.
$btnCleanWU = New-Object System.Windows.Forms.Button
$btnCleanWU.Dock = 'Fill'
$btnCleanWU.Margin = New-Object System.Windows.Forms.Padding(6)
$btnCleanWU.Text = "Clean Windows Update"
$btnCleanWU.Font = $font
$btnCleanWU.FlatStyle = 'Flat'
$btnCleanWU.UseVisualStyleBackColor = $false
$btnCleanWU.BackColor = [System.Drawing.Color]::FromArgb(0,120,212)
$btnCleanWU.ForeColor = [System.Drawing.Color]::White
$btnCleanWU.Add_Click({
    $content = @'
 # begin error-handled block
 try {
 # stop Windows Update service
     & cmd.exe /c net stop wuauserv
 # cache download folder path
     $p = "C:\Windows\SoftwareDistribution\Download"
 # delete cache contents
     if (Test-Path $p) { Remove-Item -Path $p -Recurse -Force }
 # recreate folder
     New-Item -ItemType Directory -Path $p -Force | Out-Null
 # start Windows Update service
     & cmd.exe /c net start wuauserv
 # success message
     Write-Host "Windows Update cache cleaned"
 # handle any exception
 } catch {
 # failure message
     Write-Host "Windows Update cleaning failed"
 }
'@
    RunInSeparatePSWindow $content
})
AddButtonWithInfo $grid 1 2 $btnCleanWU "Stops wuauserv, deletes C:\Windows\SoftwareDistribution\Download`nRecreates folder and restarts wuauserv`nFixes common Windows Update cache issues"
# Button: Clear Defender scan history
# Purpose: Remove Windows Defender scan history records.
# What it does:
# - Deletes contents under 'C:\ProgramData\Microsoft\Windows Defender\Scans\History\Service'.
# Notes: Does not disable Defender; only clears history.
# Feedback: Shows completion or errors in the separate window.
$btnDefender = New-Object System.Windows.Forms.Button
$btnDefender.Dock = 'Fill'
$btnDefender.Margin = New-Object System.Windows.Forms.Padding(6)
$btnDefender.Text = "Clear Defender history"
$btnDefender.Font = $font
$btnDefender.FlatStyle = 'Flat'
$btnDefender.UseVisualStyleBackColor = $false
$btnDefender.BackColor = [System.Drawing.Color]::FromArgb(0,120,212)
$btnDefender.ForeColor = [System.Drawing.Color]::White
$btnDefender.Add_Click({
    $content = @'
 # begin error-handled block
 try {
 # Defender scan history directory
     $root = "C:\ProgramData\Microsoft\Windows Defender\Scans\History\Service"
 # remove history
     if (Test-Path $root) { Get-ChildItem -Path $root -Recurse -Force -ErrorAction SilentlyContinue | Remove-Item -Force -Recurse -ErrorAction SilentlyContinue }
 # success message
     Write-Host "Defender history cleared"
 # handle any exception
 } catch {
 # failure message
     Write-Host "Operation failed"
 }
'@
    RunInSeparatePSWindow $content
})
