# Button: Remove Windows 11 bundled apps
# Purpose: Debloat preinstalled UWP apps on Windows 11.
# What it does:
# - Removes most system UWP apps for all users, excluding a safe whitelist (e.g., Notepad).
# Notes: Use cautiously; some features may rely on these apps.
# Feedback: Prints removal progress; window stays open.
# Button: Enable Hyper-V
# Purpose: Enable Hyper-V virtualization platform.
# What it does:
# - Adds required servicing packages and enables the Hyper-V feature via DISM.
# Requirements: CPU virtualization support (Intel VT-x/AMD-V), admin privileges.
# Feedback: Shows steps and completion; may require reboot.
$btnHyperV = New-Object System.Windows.Forms.Button
$btnHyperV.Dock = 'Fill'
$btnHyperV.Margin = New-Object System.Windows.Forms.Padding(6)
$btnHyperV.Text = "Enable Hyper-V"
$btnHyperV.Font = $font
$btnHyperV.FlatStyle = 'Flat'
$btnHyperV.UseVisualStyleBackColor = $false
$btnHyperV.BackColor = [System.Drawing.Color]::FromArgb(0,120,212)
$btnHyperV.ForeColor = [System.Drawing.Color]::White
$btnHyperV.Add_Click({
    $content = @'
 # begin error-handled block
 try {
 # enumerate Hyper-V packages
     $pkgs = Get-ChildItem -Path "$env:SystemRoot\servicing\Packages" -Filter "*Hyper-V*.mum" -ErrorAction SilentlyContinue
 # add each package
     foreach ($f in $pkgs) {
 # add package to image
         & dism.exe /online /norestart /add-package:$($f.FullName)
     }
 # enable Hyper-V feature
     & dism.exe /online /enable-feature /featurename:Microsoft-Hyper-V -All /LimitAccess /ALL
 # success message
     Write-Host "Hyper-V enabled"
 # handle any exception
 } catch {
 # failure message
     Write-Host "Enablement failed"
 }
'@
    RunInSeparatePSWindow $content
})
